import { nativeGlobalSpatialSamples } from "./scan-native-global-sampling";
import type { NativeGlobalQueryGeometry } from "./scan-native-global-query";

const threshold = 0.9238795325112867,
  epsilon = 2 ** -23;
// Fixed 4 x 8 palette generated by the original angular-grid constructor.
// These RGB bytes become correspondence labels, independent of display colors.
const normalColors = [
  16059125, 14093045, 12192501, 10226421, 8325877, 6425333, 4459253, 2558709,
  16059066, 14100410, 12207546, 10307002, 8340922, 6440378, 4539834, 2573498,
  16059007, 14100351, 12207487, 10314367, 8421504, 6455167, 4554623, 2588543,
  16058948, 14100292, 12207429, 10314309, 8355653, 6462789, 4569669, 2603588,
];
export interface NativeGlobalNormalCell {
  points: number[];
  normal: number[];
  flags: number;
  color: number;
}
export interface NativeGlobalSceneScan {
  id: string;
  geometry: NativeGlobalQueryGeometry;
}
export interface NativeGlobalSceneGrid {
  dimensions: number[];
  size: number[];
  scale: number[];
  origin: number[];
  lower: number[];
  upper: number[];
  occupied: Map<number, number>;
  flags: Uint8Array;
}
const nonzero = (v: readonly number[], tolerance: number) =>
  v[0] !== v[1] || v[0] !== v[2] || v[0] > tolerance || v[0] < -tolerance;
function normalized(v: number[]) {
  const length = Math.sqrt(v[0] * v[0] + v[1] * v[1] + v[2] * v[2]);
  if (length >= Number.EPSILON) {
    const reciprocal = 1 / length;
    for (let i = 0; i < 3; i++) v[i] *= reciprocal;
  }
  return v;
}
function dot(normal: readonly number[], x: number, y: number, z: number) {
  return nonzero(normal, Number.EPSILON)
    ? normal[0] * x + normal[1] * y + normal[2] * z
    : 0;
}
function angular(x: number, y: number, z: number) {
  if (z < -1 || z > 1)
    throw Error("Global scene normals require Z within [-1,1].");
  const polar = Math.min(
    3,
    Math.trunc(Math.fround(Math.acos(z)) * (1 / (Math.PI / 4))),
  );
  let azimuth = Math.fround(Math.atan2(y, x));
  if (azimuth < 0) azimuth += Math.PI * 2;
  return polar * 8 + (Math.trunc(azimuth * (1 / (Math.PI / 4))) % 8);
}
function mean(
  cell: NativeGlobalNormalCell,
  normal: (id: number) => readonly number[],
) {
  const sum = [0, 0, 0];
  for (const id of cell.points) {
    const n = normal(id);
    for (let a = 0; a < 3; a++) sum[a] = n[a] + sum[a];
  }
  cell.normal = normalized(sum);
}
export function nativeGlobalCommonNormals(
  scans: readonly NativeGlobalSceneScan[],
) {
  const cells: NativeGlobalNormalCell[] = Array.from(
    { length: 32 },
    (_, index) => ({
      points: [],
      normal: [0, 0, 0],
      flags: 0,
      color: normalColors[index],
    }),
  );
  const offsets: number[] = [];
  let count = 0;
  for (const scan of scans) {
    offsets.push(count);
    const g = scan.geometry;
    if (
      !(g.points instanceof Float32Array) ||
      !(g.normals instanceof Float32Array) ||
      g.points.length % 3 ||
      g.normals.length !== g.points.length ||
      !g.points.every(Number.isFinite) ||
      !g.normals.every(Number.isFinite) ||
      (g.flags &&
        (!(g.flags instanceof Uint32Array) ||
          g.flags.length !== g.points.length / 3)) ||
      (g.labels &&
        (!(g.labels instanceof Uint32Array) ||
          g.labels.length !== g.points.length / 3))
    )
      throw Error(
        "Global scene requires matching finite Float32 positions and normals.",
      );
    for (let i = 0; i < g.points.length / 3; i++) {
      const x = g.normals[i * 3],
        y = g.normals[i * 3 + 1],
        z = g.normals[i * 3 + 2];
      if (nonzero([x, y, z], epsilon))
        cells[angular(x, y, z)].points.push(count + i);
    }
    count += g.points.length / 3;
  }
  const normal = (id: number) => {
    let index = offsets.length - 1;
    while (index > 0 && offsets[index] > id) index--;
    const n = scans[index].geometry.normals,
      p = (id - offsets[index]) * 3;
    return [n[p], n[p + 1], n[p + 2]];
  };
  for (const cell of cells) if (cell.points.length) mean(cell, normal);
  while (true) {
    let chosen = -1,
      largest = 50;
    for (let i = 0; i < 32; i++)
      if (!(cells[i].flags & 1) && cells[i].points.length > largest) {
        largest = cells[i].points.length;
        chosen = i;
      }
    if (chosen < 0) break;
    const target = cells[chosen];
    target.flags = 1;
    mean(target, normal);
    const absorb = (index: number) => {
      if (index === chosen) return;
      const remaining: number[] = [];
      for (const id of cells[index].points) {
        const n = normal(id);
        if (dot(target.normal, n[0], n[1], n[2]) >= threshold)
          target.points.push(id);
        else remaining.push(id);
      }
      cells[index].points = remaining;
    };
    const row = Math.floor(chosen / 8),
      column = chosen % 8;
    if (row === 0 || row === 3)
      for (let c = 0; c < 8; c++) if (c !== column) absorb(row * 8 + c);
    for (let r = Math.max(0, row - 1); r <= Math.min(3, row + 1); r++)
      for (let c = column - 1; c <= column + 1; c++)
        absorb(r * 8 + ((c + 8) % 8));
  }
  // Empty bins deliberately retain their previous mean, as in the original.
  for (const cell of cells) if (cell.points.length) mean(cell, normal);
  return { cells, offsets };
}
function sourceNormals(
  scan: NativeGlobalSceneScan,
  common: readonly NativeGlobalNormalCell[],
) {
  const cells = common.map((cell) => ({
    points: [] as number[],
    normal: [...cell.normal],
    flags: cell.flags,
    color: cell.color,
  }));
  const g = scan.geometry;
  for (let i = 0; i < g.points.length / 3; i++) {
    const x = g.normals[i * 3],
      y = g.normals[i * 3 + 1],
      z = g.normals[i * 3 + 2];
    if (!nonzero([x, y, z], epsilon)) continue;
    let index = cells.findIndex(
      (cell) => dot(cell.normal, x, y, z) >= threshold,
    );
    if (index < 0) index = angular(x, y, z);
    cells[index].points.push(i);
  }
  for (const cell of cells) {
    if (cell.points.length < 100) cell.points = [];
  }
  return cells;
}
export function nativeGlobalSpatialGrid(
  bounds: readonly number[],
  spacing: number,
): NativeGlobalSceneGrid {
  if (
    bounds.length !== 6 ||
    !bounds.every(Number.isFinite) ||
    !Number.isInteger(spacing) ||
    spacing < 1 ||
    spacing > 0xffffffff ||
    bounds.some((v, i) => i < 3 && v > bounds[i + 3])
  )
    throw Error(
      "Global spatial grid requires finite ordered Float32 bounds and positive uint32 spacing.",
    );
  const extent = [0, 1, 2].map((i) =>
      Math.fround(Math.fround(bounds[i + 3]) - Math.fround(bounds[i])),
    ),
    dimensions = extent.map((v) => Math.trunc(v / spacing + 1));
  const count = dimensions[0] * dimensions[1] * dimensions[2];
  if (!Number.isSafeInteger(count) || count < 1 || count > 2_000_000)
    throw Error("Global spatial grid exceeds the two-million-cell admission.");
  const size = extent.map((v, i) => v / dimensions[i] + 0.001),
    scale = size.map((v) => (v === 0 ? 1 : 1 / v)),
    origin = size.map(
      (v, i) => Math.fround(bounds[i]) - (dimensions[i] * v - extent[i]) * 0.5,
    );
  return {
    dimensions,
    size,
    scale,
    origin,
    lower: origin.map(Math.fround),
    upper: origin.map((v, i) => Math.fround(dimensions[i] * size[i] + v)),
    occupied: new Map(),
    flags: new Uint8Array(count),
  };
}
export function nativeGlobalSpatialLookup(
  grid: NativeGlobalSceneGrid,
  p: readonly number[],
) {
  const indices: number[] = [];
  for (let a = 0; a < 3; a++) {
    if (
      p[a] < Math.fround(grid.lower[a] - epsilon) ||
      p[a] > Math.fround(grid.upper[a] + epsilon)
    )
      return -1;
    const index =
      Math.abs(p[a] - grid.upper[a]) < epsilon
        ? grid.dimensions[a] - 1
        : Math.trunc((p[a] - grid.origin[a]) * grid.scale[a]) >>> 0;
    if (index >= grid.dimensions[a]) return -1;
    indices.push(index);
  }
  return (
    (indices[0] * grid.dimensions[1] + indices[1]) * grid.dimensions[2] +
    indices[2]
  );
}
function gridBounds(grid: NativeGlobalSceneGrid, id: number) {
  const z = id % grid.dimensions[2],
    y = Math.floor(id / grid.dimensions[2]) % grid.dimensions[1],
    x = Math.floor(id / (grid.dimensions[1] * grid.dimensions[2]));
  const axes = [x, y, z];
  return [
    ...axes.map((v, a) => Math.fround(v * grid.size[a] + grid.origin[a])),
    ...axes.map((v, a) => Math.fround((v + 1) * grid.size[a] + grid.origin[a])),
  ];
}
function expandedLookup(
  grid: NativeGlobalSceneGrid,
  p: readonly number[],
  radius: number,
) {
  const indices: number[] = [];
  for (let a = 0; a < 3; a++) {
    if (p[a] < grid.lower[a] - radius || p[a] > grid.upper[a] + radius)
      return -1;
    const value = Math.min(grid.upper[a], Math.max(grid.lower[a], p[a]));
    indices.push(
      Math.min(
        grid.dimensions[a] - 1,
        Math.trunc((value - grid.origin[a]) * grid.scale[a]) >>> 0,
      ),
    );
  }
  return (
    (indices[0] * grid.dimensions[1] + indices[1]) * grid.dimensions[2] +
    indices[2]
  );
}
/** Original scan-only normal/spatial preparation and complete two-level sampler.
 * Explicit clocks permit exact native replay without sharing mutable rand state.
 * Sparse working cells retain native linear-cell order and quota arithmetic. */
export function nativeGlobalPrepareScene(
  scans: readonly NativeGlobalSceneScan[],
  options: {
    spacing?: number;
    radius?: number;
    budget?: number;
    mask?: number;
    clock: (source: number) => number;
  },
) {
  const spacing = options.spacing ?? 12,
    radius = options.radius ?? 5,
    budget = options.budget ?? 1000,
    mask = options.mask ?? 0;
  if (
    !Number.isFinite(radius) ||
    radius < 0 ||
    !Number.isInteger(budget) ||
    budget < 1 ||
    budget > 1_000_000 ||
    !Number.isInteger(mask) ||
    mask < 0 ||
    mask > 0xffffffff
  )
    throw Error("Invalid global scene options.");
  const common = nativeGlobalCommonNormals(scans);
  const sources = scans.map((scan) => {
    const g = scan.geometry,
      cells = sourceNormals(scan, common.cells),
      bounds = [Infinity, Infinity, Infinity, -Infinity, -Infinity, -Infinity];
    for (let i = 0; i < g.points.length; i += 3)
      for (let a = 0; a < 3; a++) {
        const v = g.points[i + a];
        if (v < bounds[a]) bounds[a] = v;
        if (v > bounds[a + 3]) bounds[a + 3] = v;
      }
    const grid = nativeGlobalSpatialGrid(bounds, spacing);
    const labels = g.labels?.slice() ?? new Uint32Array(g.points.length / 3);
    for (const cell of cells)
      for (const id of cell.points)
        labels[id] = (labels[id] & 0xff000000) | cell.color;
    for (const cell of cells)
      for (const id of cell.points) {
        const index = nativeGlobalSpatialLookup(
          grid,
          Array.from(g.points.subarray(id * 3, id * 3 + 3)),
        );
        if (index >= 0 && !grid.occupied.has(index))
          grid.occupied.set(index, id);
      }
    return {
      scan,
      geometry: { ...g, labels },
      cells,
      bounds,
      grid,
      eligible: cells.some((cell) => cell.points.length > 0),
      sampled: 0,
    };
  });
  for (const source of sources)
    for (const id of source.grid.occupied.keys()) {
      const bounds = gridBounds(source.grid, id),
        center = [0, 1, 2].map((a) =>
          Math.fround((bounds[a] + bounds[a + 3]) * 0.5),
        );
      if (
        sources.some((other) => {
          if (other === source || !other.eligible) return false;
          const index = expandedLookup(
            other.grid,
            center,
            spacing * 0.5 + radius,
          );
          return index >= 0 && other.grid.occupied.has(index);
        })
      )
        source.grid.flags[id] = 1;
    }
  const selected = sources.map((source, index) => {
    const g = source.scan.geometry;
    const eligible = (id: number) => {
      if ((g.flags?.[id] ?? 0) & mask) return -1;
      const cell = nativeGlobalSpatialLookup(
        source.grid,
        Array.from(g.points.subarray(id * 3, id * 3 + 3)),
      );
      return cell >= 0 && source.grid.flags[cell] & 1 ? cell : -1;
    };
    const groups = source.cells.filter((cell) =>
      cell.points.some((id) => eligible(id) >= 0),
    ).length;
    if (!groups) return source.cells.map(() => [] as number[]);
    return source.cells.map((cell) => {
      const working = new Map<number, number[]>();
      for (const id of cell.points) {
        const spatial = eligible(id);
        if (spatial >= 0) {
          let ids = working.get(spatial);
          if (!ids) {
            ids = [];
            working.set(spatial, ids);
          }
          ids.push(id);
        }
      }
      const entries = [...working.entries()].sort((a, b) => a[0] - b[0]);
      const result = nativeGlobalSpatialSamples(
        entries.map(([, points]) => ({ points, flags: 1 })),
        Math.ceil(budget / groups),
        () => options.clock(index),
      );
      source.sampled += result.total;
      return result.selections.flat();
    });
  });
  return { common: common.cells, offsets: common.offsets, sources, selected };
}
